create table public.cda_orc_categorias(id uuid primary key default gen_random_uuid(),pai_id uuid references public.cda_orc_categorias(id) on delete restrict,nome text not null check(length(trim(nome))>0),codigo text not null unique,nivel integer not null check(nivel between 1 and 3),ordem integer not null,ativo boolean not null default true,criado_em timestamptz not null default now());
create function public.cda_orc_categoria_hierarquia() returns trigger language plpgsql security invoker set search_path=public as $$ declare p public.cda_orc_categorias; begin
if tg_op='UPDATE' then
 if new.pai_id is distinct from old.pai_id or new.codigo<>old.codigo or new.nivel<>old.nivel or new.ordem<>old.ordem then raise exception 'Código e posição hierárquica são permanentes';end if;
 return new;
end if;
perform pg_advisory_xact_lock(17261017);
if new.pai_id is null then new.nivel:=1;select coalesce(max(ordem),0)+1 into new.ordem from public.cda_orc_categorias where pai_id is null;new.codigo:=new.ordem::text;
else select * into p from public.cda_orc_categorias where id=new.pai_id;if not found or p.nivel>=3 then raise exception 'Pai inválido ou limite de três níveis';end if;if not p.ativo then raise exception 'Reative o nível superior antes de subdividir';end if;new.nivel:=p.nivel+1;select coalesce(max(ordem),0)+1 into new.ordem from public.cda_orc_categorias where pai_id=new.pai_id;new.codigo:=p.codigo||'.'||new.ordem::text;end if;return new;end;$$;
create trigger categoria_hierarquia before insert or update on public.cda_orc_categorias for each row execute function public.cda_orc_categoria_hierarquia();
alter table public.cda_orc_categorias enable row level security;
grant select,insert,update on public.cda_orc_categorias to authenticated;
revoke all on public.cda_orc_categorias from anon;
create policy leitura on public.cda_orc_categorias for select to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))));
create policy inclusao on public.cda_orc_categorias for insert to authenticated with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
create policy edicao on public.cda_orc_categorias for update to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita')) with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
